msacheckBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "msacheckBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "MokkenLab",
                name = "msacheck",
                version = c(1,0,0),
                options = options,
                results = msacheckResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Model Assumptions
#'
#' Checks the assumptions of the monotone homogeneity and double monotonicity 
#' models: monotonicity, invariant item ordering, nonintersection (rest-score 
#' and P-matrix methods) and local independence (conditional association), 
#' with item response function plots and plain-language interpretation.
#' 
#' @param data .
#' @param vars .
#' @param clusterVar .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showGuides .
#' @param showRepro .
#' @param naHandling .
#' @param twowaySets .
#' @param twowaySeed .
#' @param scoreRange .
#' @param scoreMin .
#' @param scoreMax .
#' @param negItems .
#' @param minsizeMode .
#' @param minsize .
#' @param checkMono .
#' @param monoMinvi .
#' @param checkIIO .
#' @param iioMethod .
#' @param iioMinviMode .
#' @param iioMinvi .
#' @param iioAlpha .
#' @param iioItemSelection .
#' @param iioOrder .
#' @param iioClusterSize .
#' @param iioOrderText .
#' @param checkRest .
#' @param restMinvi .
#' @param checkPmatrix .
#' @param pmatMinvi .
#' @param checkCA .
#' @param caWindex .
#' @param caMinsize .
#' @param caMingroup .
#' @param caNweight .
#' @param caCovweight .
#' @param critPlot .
#' @param monoPlot .
#' @param monoCurves .
#' @param iioPlot .
#' @param restPlot .
#' @param pmatPlot .
#' @param pmatType .
#' @param plotItems .
#' @param plotCI .
#' @param plotAlpha .
#' @param plotTransparency .
#' @param plotWidth .
#' @param plotHeight .
#' @param plotPointSize .
#' @param plotLineWidth .
#' @param plotNcol .
#' @param plotLegend .
#' @param plotAxisAngle .
#' @param plotYRange .
#' @param plotValueLabels .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$cacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monoGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mono} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monoPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$iioGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$iio} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iioClusters} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iioHT} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iioPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$restGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$rest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$restPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$pmatGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$pmat} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pmatPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$caGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$ca} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$caW} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$critPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibility} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibilityCode} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
msacheck <- function(
    data,
    vars,
    clusterVar = NULL,
    showKeySummary = TRUE,
    showChoicesGuide = FALSE,
    showGuides = FALSE,
    showRepro = TRUE,
    naHandling = "listwise",
    twowaySets = 1,
    twowaySeed = 2026,
    scoreRange = "observed",
    scoreMin = 0,
    scoreMax = 4,
    negItems = list(),
    minsizeMode = "auto",
    minsize = 50,
    checkMono = TRUE,
    monoMinvi = 0.03,
    checkIIO = FALSE,
    iioMethod = "MIIO",
    iioMinviMode = "auto",
    iioMinvi = 0.03,
    iioAlpha = 0.05,
    iioItemSelection = TRUE,
    iioOrder = "estimated",
    iioClusterSize = 4,
    iioOrderText = "",
    checkRest = FALSE,
    restMinvi = 0.03,
    checkPmatrix = FALSE,
    pmatMinvi = 0.03,
    checkCA = FALSE,
    caWindex = FALSE,
    caMinsize = 4,
    caMingroup = 4,
    caNweight = "noweight",
    caCovweight = "pnorm",
    critPlot = TRUE,
    monoPlot = TRUE,
    monoCurves = "both",
    iioPlot = FALSE,
    restPlot = FALSE,
    pmatPlot = FALSE,
    pmatType = "both",
    plotItems = list(),
    plotCI = TRUE,
    plotAlpha = 0.05,
    plotTransparency = 20,
    plotWidth = 0,
    plotHeight = 0,
    plotPointSize = 2,
    plotLineWidth = 0.8,
    plotNcol = 0,
    plotLegend = "bottom",
    plotAxisAngle = "a45",
    plotYRange = "full",
    plotValueLabels = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("msacheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(clusterVar)) clusterVar <- jmvcore::resolveQuo(jmvcore::enquo(clusterVar))
    if ( ! missing(negItems)) negItems <- jmvcore::resolveQuo(jmvcore::enquo(negItems))
    if ( ! missing(plotItems)) plotItems <- jmvcore::resolveQuo(jmvcore::enquo(plotItems))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(clusterVar), clusterVar, NULL),
            `if`( ! missing(negItems), negItems, NULL),
            `if`( ! missing(plotItems), plotItems, NULL))


    options <- msacheckOptions$new(
        vars = vars,
        clusterVar = clusterVar,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showGuides = showGuides,
        showRepro = showRepro,
        naHandling = naHandling,
        twowaySets = twowaySets,
        twowaySeed = twowaySeed,
        scoreRange = scoreRange,
        scoreMin = scoreMin,
        scoreMax = scoreMax,
        negItems = negItems,
        minsizeMode = minsizeMode,
        minsize = minsize,
        checkMono = checkMono,
        monoMinvi = monoMinvi,
        checkIIO = checkIIO,
        iioMethod = iioMethod,
        iioMinviMode = iioMinviMode,
        iioMinvi = iioMinvi,
        iioAlpha = iioAlpha,
        iioItemSelection = iioItemSelection,
        iioOrder = iioOrder,
        iioClusterSize = iioClusterSize,
        iioOrderText = iioOrderText,
        checkRest = checkRest,
        restMinvi = restMinvi,
        checkPmatrix = checkPmatrix,
        pmatMinvi = pmatMinvi,
        checkCA = checkCA,
        caWindex = caWindex,
        caMinsize = caMinsize,
        caMingroup = caMingroup,
        caNweight = caNweight,
        caCovweight = caCovweight,
        critPlot = critPlot,
        monoPlot = monoPlot,
        monoCurves = monoCurves,
        iioPlot = iioPlot,
        restPlot = restPlot,
        pmatPlot = pmatPlot,
        pmatType = pmatType,
        plotItems = plotItems,
        plotCI = plotCI,
        plotAlpha = plotAlpha,
        plotTransparency = plotTransparency,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        plotPointSize = plotPointSize,
        plotLineWidth = plotLineWidth,
        plotNcol = plotNcol,
        plotLegend = plotLegend,
        plotAxisAngle = plotAxisAngle,
        plotYRange = plotYRange,
        plotValueLabels = plotValueLabels)

    analysis <- msacheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

